+#[test]
+fn test_sort_name() {
+    let te = TestEnv::new(DEFAULT_DIRS, DEFAULT_FILES);
+
+    te.assert_output_order(
+        &[".", "--sort", "name"],
+        "a.foo
+        one/b.foo
+        one/two/c.foo
+        one/two/C.Foo2
+        one/two/three/d.foo
+        one/two/three/directory_foo/
+        e1 e2
+        one/
+        symlink
+        one/two/three/
+        one/two/",
+    );
+}
+
