+#[test]
+fn test_sort_random_seed_deterministic() {
+    let te = TestEnv::new(&[], &["a.txt", "b.txt", "c.txt", "d.txt"]);
+
+    let first = te.assert_success_and_get_ordered_output(
+        ".",
+        &["--sort", "random", "--sort-seed", "42", "."],
+    );
+    let second = te.assert_success_and_get_ordered_output(
+        ".",
+        &["--sort", "random", "--sort-seed", "42", "."],
+    );
+    assert_eq!(first, second);
+}
